package io.github.astelev.around_planet.space;
import java.util.*;
/** Inertial target directions, relative planes and time-based conjunctions; no world/chunk access. */
public final class RendezvousMath {
    public static boolean targetMode(OrbitalAttitude.Mode mode){return mode.ordinal()>=OrbitalAttitude.Mode.TARGET.ordinal();}
    public static Optional<SpaceVector> direction(OrbitalAttitude.Mode mode,SpaceState own,SpaceState target){var d=switch(mode){case TARGET->target.position().subtract(own.position());case ANTI_TARGET->own.position().subtract(target.position());case RELATIVE_PROGRADE->own.velocity().subtract(target.velocity());case RELATIVE_RETROGRADE->target.velocity().subtract(own.velocity());default->SpaceVector.ZERO;};return d.length()<1e-7?Optional.empty():Optional.of(d.scale(1/d.length()));}
    public record Planes(double inclination,SpaceVector ascending,SpaceVector descending){}
    public static Planes planes(SpaceState own,SpaceState target,double mu){var a=own.position().cross(own.velocity());var b=target.position().cross(target.velocity());if(a.length()<1e-9||b.length()<1e-9)return new Planes(Double.NaN,null,null);a=a.scale(1/a.length());b=b.scale(1/b.length());double angle=Math.toDegrees(Math.acos(Math.clamp(a.dot(b),-1,1)));var line=a.cross(b);if(line.length()<1e-8||mu<=0)return new Planes(angle,null,null);line=line.scale(1/line.length());if(a.cross(line).dot(b)<0)line=line.scale(-1);return new Planes(angle,node(own,mu,line),node(own,mu,line.scale(-1)));}
    private static SpaceVector node(SpaceState s,double mu,SpaceVector d){var h=s.position().cross(s.velocity());var e=s.velocity().cross(h).scale(1/mu).subtract(s.position().scale(1/s.position().length()));double denominator=1+e.dot(d);return denominator<=1e-8?null:d.scale(h.dot(h)/mu/denominator);}
    public record Approach(long tick,SpaceState own,SpaceState target){public double distance(){return target.position().subtract(own.position()).length();}public double speed(){return target.velocity().subtract(own.velocity()).length();}}
    public record Prediction(List<Approach> approaches,long until){}
    public static SpaceTrajectory pathAt(SpaceTrajectory base,ManeuverPreview preview,long tick){var path=base;if(preview!=null)for(var n:preview.nodes())if(n.node().tick()<=tick)path=n.after();return path;}
    public static Prediction predict(SpaceTrajectory base,ManeuverPreview preview,SpaceTrajectory target,long now,double radius,double entry){
        var finalPath=pathAt(base,preview,Long.MAX_VALUE);long last=preview==null||preview.nodes().isEmpty()?now:Math.max(now,preview.nodes().getLast().node().tick());double pa=OrbitPlot.create(finalPath.at(last),base.mu(),radius,entry,false).period(),pb=OrbitPlot.create(target.at(now),target.mu(),radius,entry,false).period();double shortest=pa>0&&pb>0?Math.min(pa,pb):Math.max(pa,pb);double horizon=pa>0||pb>0?Math.max(pa,pb)*2:3600;if(shortest>0)horizon=Math.min(horizon,shortest*128);horizon=Math.max(60,horizon);long until=ManeuverPreview.tickAt(last,horizon);
        var targetEllipse=EllipticArc.of(target.at(now),target.mu());if(targetEllipse!=null){var arc=targetEllipse.full(radius+entry,384);if(arc.reentry()&&!arc.vertices().isEmpty())until=Math.min(until,ManeuverPreview.tickAt(now,arc.vertices().getLast().seconds()));}
        if(preview!=null&&!preview.segments().isEmpty()){var seg=preview.segments().getLast();if(OrbitPlot.create(seg.trajectory().at(seg.points().getFirst().tick()),base.mu(),radius,entry,false).reentry())until=Math.min(until,seg.points().getLast().tick());}if(until<=now)return new Prediction(List.of(),now);
        var times=new TreeSet<Long>();times.add(now);times.add(until);for(int i=1;i<2048;i++)times.add(now+(long)((until-now)*(i/2048.0)));
        if(preview!=null){for(var seg:preview.segments())for(var p:seg.points())if(p.tick()>=now&&p.tick()<=until)times.add(p.tick());for(var mark:preview.nodes())if(mark.node().tick()>=now&&mark.node().tick()<=until)times.add(mark.node().tick());}
        phases(times,target,now,until,radius+entry);var phasePath=base;long from=now;if(preview!=null)for(var mark:preview.nodes()){if(mark.node().tick()>until)break;phases(times,phasePath,from,mark.node().tick(),radius+entry);phasePath=mark.after();from=mark.node().tick();}phases(times,phasePath,from,until,radius+entry);
        var list=new ArrayList<>(times);var result=new ArrayList<Approach>();for(int i=1;i+1<list.size();i++){long lo=list.get(i-1),mid=list.get(i),hi=list.get(i+1);double value=score(base,preview,target,mid);double vl=score(base,preview,target,lo),vh=score(base,preview,target,hi);if(value>vl||value>vh||Math.max(vl-value,vh-value)<1e-10*Math.max(1,value))continue;for(int j=0;j<45&&hi-lo>2;j++){long x=lo+(hi-lo)/3,y=hi-(hi-lo)/3;if(score(base,preview,target,x)<=score(base,preview,target,y))hi=y;else lo=x;}long t=lo;for(long x=lo+1;x<=hi;x++)if(score(base,preview,target,x)<score(base,preview,target,t))t=x;if(result.isEmpty()||t-result.getLast().tick()>20)result.add(new Approach(t,pathAt(base,preview,t).at(t),target.at(t)));}
        result.sort(Comparator.comparingDouble(Approach::distance).thenComparingLong(Approach::tick));return new Prediction(List.copyOf(result.stream().limit(12).toList()),until);
    }
    /** Compare positions in one chart, even when the vessel changes its attracting body. */
    public static Prediction predictPatched(SpaceTrajectory base,ManeuverPreview preview,SpaceTrajectory target,long now,double radius,double entry,CelestialSystem system,String chart,boolean prescribed,int depth){
        if(preview==null||preview.segments().isEmpty())return new Prediction(List.of(),now);
        var targetPreview=prescribed?null:ManeuverPreview.create(target,now,List.of(),radius,entry,system,depth);
        long until=preview.segments().getLast().points().getLast().tick();if(targetPreview!=null&&!targetPreview.segments().isEmpty()){var last=targetPreview.segments().getLast();boolean closed=last.points().size()>1&&last.points().getFirst().position().subtract(last.points().getLast().position()).length()<1e-5;if(!closed)until=Math.min(until,last.points().getLast().tick());}if(until<=now)return new Prediction(List.of(),now);
        var times=new TreeSet<Long>();times.add(now);times.add(until);for(int i=1;i<2048;i++)times.add(now+(long)((until-now)*(i/2048.0)));for(var seg:preview.segments())for(var p:seg.points())if(p.tick()>=now&&p.tick()<=until)times.add(p.tick());if(targetPreview!=null)for(var seg:targetPreview.segments())for(var p:seg.points())if(p.tick()>=now&&p.tick()<=until)times.add(p.tick());
        final var other=targetPreview;java.util.function.LongFunction<Approach> at=t->{var ownPath=previewPath(base,preview,t);var own=system.relative(chart,system.global(ownPath.primary(),ownPath.at(t),t),t);var otherPath=other==null?target:previewPath(target,other,t);var otherState=prescribed?target.at(t):system.relative(chart,system.global(otherPath.primary(),otherPath.at(t),t),t);return new Approach(t,own,otherState);};
        var dates=new ArrayList<>(times);var result=new ArrayList<Approach>();for(int i=1;i+1<dates.size();i++){long lo=dates.get(i-1),mid=dates.get(i),hi=dates.get(i+1);double score=at.apply(mid).distance(),left=at.apply(lo).distance(),right=at.apply(hi).distance();if(score>left||score>right||Math.max(left-score,right-score)<1e-9)continue;for(int j=0;j<45&&hi-lo>2;j++){long a=lo+(hi-lo)/3,b=hi-(hi-lo)/3;if(at.apply(a).distance()<=at.apply(b).distance())hi=b;else lo=a;}long best=lo;for(long t=lo+1;t<=hi;t++)if(at.apply(t).distance()<at.apply(best).distance())best=t;long candidate=best;if(result.stream().noneMatch(a->Math.abs(a.tick()-candidate)<20))result.add(at.apply(best));}
        result.sort(Comparator.comparingDouble(Approach::distance).thenComparingLong(Approach::tick));return new Prediction(List.copyOf(result.stream().limit(12).toList()),until);
    }
    private static SpaceTrajectory previewPath(SpaceTrajectory base,ManeuverPreview preview,long tick){var path=base;for(var segment:preview.segments()){path=segment.trajectory();if(!segment.points().isEmpty()&&tick<segment.points().getLast().tick())return path;}return path;}
    private static void phases(Set<Long> times,SpaceTrajectory path,long from,long until,double shell){if(until<=from)return;var ellipse=EllipticArc.of(path.at(from),path.mu());if(ellipse==null)return;var arc=ellipse.full(shell,64);long cycles=(long)Math.ceil((until-from)/20.0/ellipse.period());long samples=Math.min(128,cycles);for(long i=0;i<=samples;i++){long cycle=cycles<=128?i:(long)(i*(cycles/(double)Math.max(1,samples)));for(var point:arc.vertices()){long tick=ManeuverPreview.tickAt(from,cycle*ellipse.period()+point.seconds());if(tick>=from&&tick<=until)times.add(tick);}}}
    private static double score(SpaceTrajectory base,ManeuverPreview preview,SpaceTrajectory target,long t){var d=pathAt(base,preview,t).at(t).position().subtract(target.at(t).position());return d.dot(d);}
    private RendezvousMath(){}
}
